import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.B4hAkGey.js";const T=JSON.parse('{"title":"EP.01 浏览器里藏着一整套 RTC 栈","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.01-what-is-webrtc.md","filePath":"comics/EP.01-what-is-webrtc.md","lastUpdated":1792683941000}'),s={name:"comics/EP.01-what-is-webrtc.md"};function d(i,t,l,n,b,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="ep-01-浏览器里藏着一整套-rtc-栈" tabindex="-1">EP.01 浏览器里藏着一整套 RTC 栈 <a class="header-anchor" href="#ep-01-浏览器里藏着一整套-rtc-栈" aria-label="Permalink to &quot;EP.01 浏览器里藏着一整套 RTC 栈&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/01-overview/basics">1.1 WebRTC 是什么</a> · <a href="./../guide/01-overview/advanced">1.2 5G 重塑实时通信</a> · <a href="./../guide/01-overview/practice">1.3 5G 场景优势定位</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君疑惑&quot;为什么抖音直播连麦能这么低延迟&quot;，以为要自己写 UDP 传输层。</td></tr><tr><td>② 揭秘</td><td>码叔画了三层架构图：浏览器把整套 RTC 栈（采集/编解码/SRTP/ICE）打包成了 JS API，开发者只调三个 API 就够了。</td></tr><tr><td>③ 实证</td><td>码叔展示了 5G 网络下 WebRTC 端到端实测 70ms vs RTMP 1.8s 的差距，像素酱问&quot;那 5G 真能到 1ms？&quot;</td></tr><tr><td>④ 结案</td><td>码叔讲清楚 5G 1ms 是空口时延不是端到端，WebRTC 三件套 + 5G MEC = 直播互动最优解。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-webrtc-三件套" tabindex="-1">① WebRTC 三件套 <a class="header-anchor" href="#_1-webrtc-三件套" aria-label="Permalink to &quot;① WebRTC 三件套&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>作用</th></tr></thead><tbody><tr><td><code>getUserMedia</code></td><td>采集音视频（摄像头 / 麦克风 / 屏幕共享）</td></tr><tr><td><code>RTCPeerConnection</code></td><td>建立 P2P 连接、交换媒体流、拥塞控制</td></tr><tr><td><code>RTCDataChannel</code></td><td>P2P 之间传输任意数据（文本、文件、二进制）</td></tr></tbody></table><blockquote><p>浏览器底层还做了一堆你看不到的事：DTLS 密钥协商、SRTP 加密、Jitter Buffer 抖动缓冲、拥塞控制（GCC / BBR）、ICE 候选选择——全是内建的。</p></blockquote><h3 id="_2-5g-延迟-1ms-端到端" tabindex="-1">② 5G 延迟 ≠ 1ms 端到端 <a class="header-anchor" href="#_2-5g-延迟-1ms-端到端" aria-label="Permalink to &quot;② 5G 延迟 ≠ 1ms 端到端&quot;">​</a></h3><p>容易混淆的点：</p><ul><li><strong>5G 空口时延</strong>：1~10ms（这是 5G 基站 ↔ 手机之间的时间）</li><li><strong>WebRTC 端到端</strong>：采集 → 编码 → 传输 → 转发 → 解码 → 渲染，5G 下实际 <strong>50~120ms</strong></li><li><strong>4G + RTMP</strong>：约 1.5~2.5 秒（GOP 缓存 + HLS 切片）</li></ul><p>5G 的核心贡献：把传输时延从 30~50ms 压到 5~15ms，再配合 MEC 边缘 SFU 减少跨区域转发。</p><h3 id="_3-何时用-webrtc-vs-rtmp" tabindex="-1">③ 何时用 WebRTC vs RTMP <a class="header-anchor" href="#_3-何时用-webrtc-vs-rtmp" aria-label="Permalink to &quot;③ 何时用 WebRTC vs RTMP&quot;">​</a></h3><p><strong>一条判断标准</strong>：是否需要互动。</p><table tabindex="0"><thead><tr><th>场景</th><th>选谁</th></tr></thead><tbody><tr><td>电商带货纯播放</td><td>RTMP / HLS（CDN 分发便宜）</td></tr><tr><td>连麦 PK / 在线教育</td><td><strong>WebRTC</strong>（必须双向互动）</td></tr><tr><td>竞技直播</td><td><strong>WebRTC + 5G MEC</strong>（低延迟 + 边缘分发）</td></tr><tr><td>云游戏</td><td><strong>WebRTC + 专用编码器</strong>（端到端 &lt; 100ms）</td></tr></tbody></table><p>现在主流做法是<strong>WebRTC 做互动层 + RTMP 做分发层</strong>——主播用 WebRTC 推流，SFU 同时转 RTMP 给传统 CDN，兼顾低延迟互动和大规模分发。</p><h3 id="_4-5g-四大赋能-webrtc-的特性" tabindex="-1">④ 5G 四大赋能 WebRTC 的特性 <a class="header-anchor" href="#_4-5g-四大赋能-webrtc-的特性" aria-label="Permalink to &quot;④ 5G 四大赋能 WebRTC 的特性&quot;">​</a></h3><ol><li><strong>eMBB 上行增强</strong>：上行从 500Mbps 到 10Gbps → 手机也能推 4K</li><li><strong>URLLC 低时延</strong>：空口 1~10ms → 端到端 50ms 量级</li><li><strong>网络切片</strong>：运营商为 WebRTC 直播切独立虚拟网络，保障 QoS</li><li><strong>MEC 边缘计算</strong>：SFU 部署到基站旁，减少 3~5 跳</li></ol><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：WebRTC 替代 RTMP 了吗？</strong> 没有。WebRTC 解决<strong>互动</strong>问题，RTMP 解决<strong>大规模分发</strong>问题。现在是互补关系：WebRTC + SFU + RTMP 转推给 CDN。</li><li><strong>Q：5G 手机一定比 4G 快吗？</strong> 不一定。取决于基站密度、室内覆盖、运营商策略。但在密集城区，5G SA（独立组网）的空口时延优势很明显。</li><li><strong>Q：WebRTC 延迟稳定吗？</strong> 网络好时很稳定（±10ms）。但弱网下会自动增 jitter buffer 导致延迟上涨。模块 9 会讲如何控制。</li><li><strong>Q：为什么不用 QUIC + WebTransport 替代 WebRTC？</strong> QUIC/WebTransport 适合<strong>数据传输</strong>，但音视频编码、SRTP、ICE 这些 WebRTC 已经成熟几十年了的组件，重造轮子没必要。现在的趋势是 WebRTC 底层逐步迁移到 QUIC（HTTP/3）。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>WebRTC 的三件套 API 分别是什么？各起什么作用？</li><li>5G URLLC 宣称的 1ms 指的是哪一段的时延？WebRTC 端到端实际能到多少？</li><li>电商直播主播和观众互动（连麦 PK）应该用什么技术？纯观看的 10w+ 并发观众呢？</li></ol><details><summary>答案</summary><ol><li><code>getUserMedia</code>（采集音视频）、<code>RTCPeerConnection</code>（建立 P2P 音视频连接）、<code>RTCDataChannel</code>（P2P 间传输任意数据）。</li><li>1ms 是<strong>空口时延</strong>（基站 ↔ 手机），不是端到端。5G SA 下 WebRTC 端到端实际 50~120ms。</li><li>连麦 PK 用 <strong>WebRTC + SFU</strong>（必须双向低延迟互动）。10w+ 纯观看观众用 <strong>RTMP 推流 + CDN HLS 分发</strong>（WebRTC 做不了这么大规模的分发，SFU 成本过高）。</li></ol></details>',23)])])}const C=e(s,[["render",d]]);export{T as __pageData,C as default};
